contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit amount is provided as a parameter; this function is payable so the harness
    // can fund the deposit. We require this contract has enough balance to forward the amount.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to fund deposit");

        // Step 1: deposit `amount` into c from this test contract
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // Record this contract's balance before the first withdraw attempt
        uint myBalBefore = address(this).balance;

        // Step 2: attempt first withdrawAll and record whether it reverted
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // Record this contract's balance after the first withdraw attempt
        uint myBalAfterFirst = address(this).balance;

        // Step 3: attempt second withdrawAll and record whether it reverted
        bool secondReverted;
        uint myBalBeforeSecond = address(this).balance;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }
        uint myBalAfterSecond = address(this).balance;

        // Observed received amounts (avoid underflow by branching on >= comparisons)
        uint receivedOnFirst = 0;
        if (myBalAfterFirst >= myBalBefore) {
            receivedOnFirst = myBalAfterFirst - myBalBefore;
        }
        uint receivedOnSecond = 0;
        if (myBalAfterSecond >= myBalBeforeSecond) {
            receivedOnSecond = myBalAfterSecond - myBalBeforeSecond;
        }

        // Assert the general rule as a single boolean expression:
        // - If first withdraw succeeded (firstReverted == false) then second received must be 0.
        // - If first withdraw reverted then any later successful withdraw (i.e., secondReverted == false)
        //   can receive at most the original deposit `amount`.
        assert(
            (
                (!firstReverted && receivedOnSecond == 0)
            ) || (
                (firstReverted && (secondReverted || receivedOnSecond <= amount))
            )
        );
    }

    receive() external payable {}
}

