// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.deposit{value: amount}() {} catch { return; }
        uint myBalBefore = address(this).balance;
        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint myBalAfterFirst = address(this).balance;
        bool secondReverted;
        uint myBalBeforeSecond = address(this).balance;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint myBalAfterSecond = address(this).balance;
        uint receivedOnFirst = 0;
        if (myBalAfterFirst >= myBalBefore) {
            receivedOnFirst = myBalAfterFirst - myBalBefore;
        }
        uint receivedOnSecond = 0;
        if (myBalAfterSecond >= myBalBeforeSecond) {
            receivedOnSecond = myBalAfterSecond - myBalBeforeSecond;
        }
        assertTrue((
                (!firstReverted && receivedOnSecond == 0)
            ) || (
                (firstReverted && (secondReverted || receivedOnSecond <= amount))
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
